// Filtrer les articles d'aujourd'hui et construire le digest
const today = new Date();
const todayStr = today.toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric' });

const allItems = $input.all();

// Filtrer les articles du jour avec importance Élevée ou Moyenne
const todayItems = allItems.filter(item => {
  const d = item.json['Date de collecte'] || '';
  return d.startsWith(todayStr) || d.includes(todayStr);
});

const elevated = todayItems.filter(i => i.json['Importance'] === 'Élevée');
const medium   = todayItems.filter(i => i.json['Importance'] === 'Moyenne');
const competitors = todayItems.filter(i => i.json['Banque concurrente'] && i.json['Banque concurrente'].trim() !== '');
const opportunities = todayItems.filter(i => i.json['Opportunité'] && i.json['Opportunité'].trim() !== '');
const threats  = todayItems.filter(i => i.json['Menace'] && i.json['Menace'].trim() !== '');

if (todayItems.length === 0) {
  return [{ json: { _skip: true, message: 'Aucun article collecté aujourd\'hui' } }];
}

// Sérialiser pour le prompt OpenAI
const formatArticle = (item, idx) => {
  const j = item.json;
  return `${idx + 1}. [${j['Importance'] || ''}] ${j['Titre'] || ''}
   Source: ${j['Source'] || ''} | Catégorie: ${j['Catégorie'] || ''}
   Signal: ${j['Type de signal'] || ''}
   Résumé: ${j['Résumé'] || ''}
   Opportunité: ${j['Opportunité'] || 'N/A'}
   Menace: ${j['Menace'] || 'N/A'}
   Action: ${j['Action recommandée'] || 'N/A'}`;
};

const topArticles = [...elevated, ...medium].slice(0, 15);
const articlesText = topArticles.map(formatArticle).join('\n\n');

return [{
  json: {
    date: todayStr,
    total: todayItems.length,
    nb_eleves: elevated.length,
    nb_moyens: medium.length,
    nb_concurrents: competitors.length,
    articles_text: articlesText,
    elevated_items: elevated.slice(0, 8).map(i => i.json),
    medium_items: medium.slice(0, 6).map(i => i.json),
    competitor_items: competitors.slice(0, 5).map(i => i.json),
    opportunity_items: opportunities.slice(0, 5).map(i => i.json),
    threat_items: threats.slice(0, 5).map(i => i.json)
  }
}];

